ALTER TABLE content_items ADD COLUMN content_type TEXT NOT NULL DEFAULT 'post';
CREATE INDEX IF NOT EXISTS idx_content_type_status ON content_items(content_type,status);
CREATE TABLE IF NOT EXISTS plugin_content_types (plugin_id TEXT NOT NULL REFERENCES plugin_installations(plugin_id) ON DELETE CASCADE, type_id TEXT NOT NULL, label TEXT NOT NULL, supports_json TEXT NOT NULL, PRIMARY KEY(plugin_id,type_id));
CREATE TABLE IF NOT EXISTS plugin_meta_definitions (plugin_id TEXT NOT NULL REFERENCES plugin_installations(plugin_id) ON DELETE CASCADE, scope TEXT NOT NULL CHECK(scope IN ('content','user')), meta_key TEXT NOT NULL, value_type TEXT NOT NULL CHECK(value_type IN ('string','number','boolean','json')), required INTEGER NOT NULL DEFAULT 0, schema_json TEXT NOT NULL DEFAULT '{}', PRIMARY KEY(plugin_id,scope,meta_key));
CREATE TABLE IF NOT EXISTS content_meta (content_id INTEGER NOT NULL REFERENCES content_items(id) ON DELETE CASCADE, meta_key TEXT NOT NULL, value_json TEXT NOT NULL, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(content_id,meta_key));
CREATE TABLE IF NOT EXISTS user_meta (user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, meta_key TEXT NOT NULL, value_json TEXT NOT NULL, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(user_id,meta_key));
CREATE TABLE IF NOT EXISTS plugin_actions (plugin_id TEXT NOT NULL REFERENCES plugin_installations(plugin_id) ON DELETE CASCADE, action_id TEXT NOT NULL, label TEXT NOT NULL, entity_scope TEXT NOT NULL CHECK(entity_scope IN ('content','user','site')), PRIMARY KEY(plugin_id,action_id));
